const photos = $input.all();
if (!photos.length) {
  throw new Error('No media_forensics rows found for this intake_id');
}

const intake_id = photos[0].json.intake_id;
const batch_id = photos[0].json.batch_id;

// Pull gender from the Supabase Get Single node
const gender = $('Merge: Single + Batch').first().json.gender ?? null;

const now = new Date();
const photoUrls = photos
  .filter(p => {
    if (!p.json.retool_signed_url) return false;
    if (!p.json.retool_url_expires_at) return false;
    return new Date(p.json.retool_url_expires_at) > now;
  })
  .map(p => ({
    id: p.json.id,
    url: p.json.retool_signed_url,
    photo_type: p.json.photo_type,
    r2_object_key: p.json.r2_object_key
  }));

if (photoUrls.length === 0) {
  throw new Error('All signed URLs are null or expired for intake_id: ' + intake_id + '. Run URL refresh first.');
}

return [{
  json: {
    intake_id,
    batch_id,
    gender,
    photo_urls: photoUrls,
    images_in_batch: photoUrls.length
  }
}];

const response = $input.first().json;
const gemini_raw = response.candidates[0].content.parts[0].text;
const cleaned = gemini_raw
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

let result;
try {
  result = JSON.parse(cleaned);
} catch(e) {
  result = {
    structural_metrics: {},
    active_category_scores: {},
    structural_confidence: 'Low'
  };
}

const sm  = result.structural_metrics || {};
const acs = result.active_category_scores || {};

const intake_id = $('Code: Build Structural Prompt').first().json.intake_id;
const batch_id  = $('Code: Build Structural Prompt').first().json.batch_id;
const gender    = $('Code: Build Structural Prompt').first().json.gender;

return [{
  json: {
    intake_id,
    batch_id,
    gender,

    // ── UNIVERSAL STRUCTURAL ─────────────────────────────────────
    symmetry_score:            sm.symmetry_score            ?? null,
    memorability_index:        sm.memorability_index        ?? null,
    androgyny_score:           sm.androgyny_score           ?? null,
    overall_body_proportion:   sm.overall_body_proportion   ?? null,
    cheek_to_jaw_ratio:        sm.cheek_to_jaw_ratio        ?? null,
    interpupillary_index:      sm.interpupillary_index      ?? null,
    facial_thirds_balance:     sm.facial_thirds_balance     ?? null,
    intercanthal_distance:     sm.intercanthal_distance     ?? null,
    shoulder_line:             sm.shoulder_line             ?? null,

    // ── FEMALE ───────────────────────────────────────────────────
    jaw_definition:            sm.jaw_definition            ?? null,
    cheekbone_structure:       sm.cheekbone_structure       ?? null,
    supraorbital_ridge_score:  sm.supraorbital_ridge_score  ?? null,
    smile_corridor:            sm.smile_corridor            ?? null,
    clavicle_prominence:       sm.clavicle_prominence       ?? null,
    leg_to_body_ratio:         sm.leg_to_body_ratio         ?? null,
    razor_jaw_angle:           sm.razor_jaw_angle           ?? null,

    // ── MALE ─────────────────────────────────────────────────────
    jawline_squareness:        sm.jawline_squareness        ?? null,
    brow_ridge_strength:       sm.brow_ridge_strength       ?? null,
    shoulder_to_waist_ratio:   sm.shoulder_to_waist_ratio   ?? null,
    neck_definition:           sm.neck_definition           ?? null,
    height_to_torso_ratio:     sm.height_to_torso_ratio     ?? null,
    facial_hair_versatility:   sm.facial_hair_versatility   ?? null,

    // ── NON-BINARY ───────────────────────────────────────────────
    facial_gender_read:        sm.facial_gender_read        ?? null,
    androgyny_casting_fit:     sm.androgyny_casting_fit     ?? null,

    // ── EXTENDED STRUCTURAL ──────────────────────────────────────
    zygomatic_ratio:           result.zygomatic_ratio       ?? null,
    zygomatic_confidence:      result.zygomatic_confidence  ?? null,
    symmetry_variance:         result.symmetry_variance     ?? null,
    versatility_flag:          result.versatility_flag      ?? null,

    // ── AESTHETIC (INTRINSIC) ────────────────────────────────────
    aesthetic_category:        result.aesthetic_category    ?? null,
    aesthetic_sub_type:        result.aesthetic_sub_type    ?? null,
    active_category_scores:    acs,   // kept as object for stage 2 consumption
    visual_summary:            result.visual_summary        ?? null,

    // ── CONFIDENCE ───────────────────────────────────────────────
    structural_confidence:     result.structural_confidence ?? null,
  }
}];

// ── INPUT DATA ──────────────────────────────────────────────────────
const d = $('Code: Parse Analysis Result').first().json;
const cfg = $('Read Agency Slug').first().json.fields;

// ── CATEGORY WEIGHTS ────────────────────────────────────────────────
const categoryWeights = JSON.parse(
  cfg['Aesthetic Category Weights JSON']
);

// ── ACTIVE CATEGORIES ───────────────────────────────────────────────
const activeEntries = Object.entries(categoryWeights)
  .filter(([k, v]) => k !== 'denominator' && v > 0);

const categoryList = activeEntries
  .map(([k]) => k)
  .join(', ');

// ── TIER LABELS ─────────────────────────────────────────────────────
const tier1 = cfg['Rank Label Tier 1'];
const tier2 = cfg['Rank Label Tier 2'];
const tier3 = cfg['Rank Label Tier 3'];
const tier4 = cfg['Rank Label Tier 4'];

// ── OPTIONAL SCORING ANCHORS ───────────────────────────────────────
const anchors = cfg['Scoring Anchors JSON']
  ? JSON.parse(cfg['Scoring Anchors JSON'])
  : {};

const anchorBlock = Object.keys(anchors).length > 0
  ? Object.entries(anchors)
      .filter(([cat]) =>
        activeEntries.find(([k]) => k === cat)
      )
      .map(([cat, levels]) =>
`${cat}
95+: ${levels['95_plus']}
75-84: ${levels['75_84']}
55-74: ${levels['55_74']}
Below 55: ${levels['below_55']}`
      )
      .join('\n\n')
  : '';

// ── FILTER STRUCTURAL METRICS ──────────────────────────────────────
const structuralMetrics = Object.fromEntries(
  Object.entries({
    symmetry_score:            d.symmetry_score,
    memorability_index:        d.memorability_index,
    androgyny_score:           d.androgyny_score,
    overall_body_proportion:   d.overall_body_proportion,
    cheek_to_jaw_ratio:        d.cheek_to_jaw_ratio,
    interpupillary_index:      d.interpupillary_index,
    facial_thirds_balance:     d.facial_thirds_balance,
    intercanthal_distance:     d.intercanthal_distance,
    shoulder_line:             d.shoulder_line,
    jaw_definition:            d.jaw_definition,
    cheekbone_structure:       d.cheekbone_structure,
    supraorbital_ridge_score:  d.supraorbital_ridge_score,
    smile_corridor:            d.smile_corridor,
    clavicle_prominence:       d.clavicle_prominence,
    leg_to_body_ratio:         d.leg_to_body_ratio,
    razor_jaw_angle:           d.razor_jaw_angle,
    jawline_squareness:        d.jawline_squareness,
    brow_ridge_strength:       d.brow_ridge_strength,
    shoulder_to_waist_ratio:   d.shoulder_to_waist_ratio,
    neck_definition:           d.neck_definition,
    height_to_torso_ratio:     d.height_to_torso_ratio,
    facial_hair_versatility:   d.facial_hair_versatility,
    facial_gender_read:        d.facial_gender_read,
    androgyny_casting_fit:     d.androgyny_casting_fit,
    zygomatic_ratio:           d.zygomatic_ratio,
    symmetry_variance:         d.symmetry_variance,
    photo_quality_score:       d.photo_quality_score
  }).filter(([_, v]) => v !== null && v !== undefined)
);

// ── CATEGORY SCORES ────────────────────────────────────────────────
const categoryScores = d.active_category_scores || {};

// ── DOMINANT CATEGORY ───────────────────────────────────────────────
const dominantEntry = Object.entries(categoryScores)
  .sort(([, a], [, b]) => b - a)[0];

const dominantCategory      = dominantEntry?.[0] ?? null;
const dominantCategoryScore = dominantEntry?.[1] ?? null;

// ── AGENCY WEIGHTED SCORE ───────────────────────────────────────────
const agencyWeightedScore = dominantCategory && categoryWeights[dominantCategory]
  ? +(dominantCategoryScore * (categoryWeights[dominantCategory] / 100)).toFixed(2)
  : null;

// ── PROMPT ─────────────────────────────────────────────────────────
const prompt = `
You are Talent Prism Stage 2: Agency Fit & Ranking Engine.

Stage 1 has already determined:
- structural geometry
- intrinsic aesthetic identity
- category tendencies
- visual memorability

You MUST treat Stage 1 outputs as ground truth.

Your task:
1. Evaluate agency compatibility
2. Evaluate market fit
3. Evaluate booking potential
4. Evaluate brand alignment
5. Produce final ranking assessment

Do NOT re-evaluate the applicant visually.

Return ONLY valid JSON.

-------------------------------------
GLOBAL RULES
-------------------------------------

- Agency fit is relative, not universal
- Strong faces may still mismatch an agency
- Weak category alignment should score low
- Use full scoring range
- Most applicants should NOT exceed 75
- Scores above 90 should be rare
- Distinctiveness only matters if aligned with agency positioning
- Commercial viability does NOT imply editorial fit
- Avoid optimism bias
- Be selective
- Do not inflate scores
- score_reasoning must be 2-3 compact sentences maximum
- No verbose elaboration
- If photo_quality_score is below 50, reduce ranking_confidence and increase scoring skepticism

-------------------------------------
STAGE 1 VISUAL PROFILE
-------------------------------------

Gender:
${d.gender}

Structural metrics:
${JSON.stringify(structuralMetrics, null, 2)}

Intrinsic category scores:
${JSON.stringify(categoryScores, null, 2)}

Dominant category: ${dominantCategory ?? 'unknown'}
Dominant category score: ${dominantCategoryScore ?? 'unknown'}
Agency weighted score (dominant × agency weight): ${agencyWeightedScore ?? 'unknown'}

Primary intrinsic category:
${d.aesthetic_category ?? 'Not provided'}

Aesthetic sub-type:
${d.aesthetic_sub_type ?? 'Not provided'}

Visual summary:
${d.visual_summary ?? 'Not provided'}

Structural confidence:
${d.structural_confidence ?? 'Not provided'}

-------------------------------------
AGENCY CONTEXT
-------------------------------------

Agency:
${cfg['Agency Slug']}

Primary markets:
${cfg['Primary Markets (City)']}

Brand relationships:
${cfg['Brand Relationships']}

Agency categories:
${cfg['Aesthetic Categories']}

Category priority weights:
${JSON.stringify(categoryWeights, null, 2)}

-------------------------------------
SCORING LOGIC
-------------------------------------

Use the agency weighted score as your scoring anchor.
Adjust up or down based on:

- How well the dominant category matches agency positioning
- Booking realism for the stated markets
- Brand visual alignment
- Whether memorability is relevant to agency needs
- Structural confidence (Low confidence = widen uncertainty, reduce scores)
- Photo quality (below 50 = increase skepticism on edge-case scores)

Category weights are guidance signals, NOT rigid arithmetic.

Penalize heavily if:
- Dominant category mismatches agency priorities
- Face is visually generic relative to agency positioning
- Market fit is weak
- Structural confidence is Low

-------------------------------------
CALIBRATION
-------------------------------------

${anchorBlock || 'No scoring anchors provided.'}

-------------------------------------
FINAL VERDICT TIERS
-------------------------------------

Allowed verdict values:
- ${tier1}
- ${tier2}
- ${tier3}
- ${tier4}

-------------------------------------
RETURN JSON
-------------------------------------

Produce score_reasoning FIRST before all numeric scores.

{
  "score_reasoning": "2 sentences. Agency fit or mismatch only. Reference dominant category score and final_agency_score.",

  "dominant_category_score": ${dominantCategoryScore ?? 0.0},

  "agency_weighted_score": ${agencyWeightedScore ?? 0.0},

  "structural_score": 0.0,

  "aesthetic_score": 0.0,

  "final_agency_score": 0.0,

  "primary_agency_fit_category":
    "<one category from: ${categoryList}>",

  "market_fit": {
    "primary_market": "string",
    "secondary_market": "string"
  },


  "booking_potential":
    "low" | "moderate" | "strong" | "elite",

  "ranking_confidence":
    "Low" | "Medium" | "High",

  "final_verdict": "string"
}

Rules:
- final_verdict must be one of the allowed verdict tiers
- dominant_category_score and agency_weighted_score are pre-computed — do not override them
- Return ONLY valid JSON
- No markdown
- No extra text
`;
return [{
  json: {
    prompt,
    intake_id: d.intake_id
  }
}];

const response = $input.first().json;
const raw = response.content[0].text;

const cleaned = raw
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

let result;
try {
  result = JSON.parse(cleaned);
} catch(e) {
  result = {
    error: 'JSON parse error',
    raw
  };
}

const intake_id = $('Code: Build Stage 2 Prompt').first().json.intake_id;

return [{
  json: {
    intake_id,
    score_reasoning:             result.score_reasoning              ?? null,
    dominant_category_score:     result.dominant_category_score      ?? null,
    agency_weighted_score:       result.agency_weighted_score        ?? null,
    structural_score:            result.structural_score             ?? null,
    aesthetic_score:             result.aesthetic_score              ?? null,
    final_agency_score:          result.final_agency_score           ?? null,
    primary_agency_fit_category: result.primary_agency_fit_category  ?? null,
    market_fit_primary:          result.market_fit?.primary_market   ?? null,
    market_fit_secondary:        result.market_fit?.secondary_market ?? null,
    booking_potential:           result.booking_potential            ?? null,
    ranking_confidence:          result.ranking_confidence           ?? null,
    final_verdict:               result.final_verdict                ?? null
  }
}];
